INSERT INTO doctors (user_id, name, specialization, department, email, available)
SELECT u.user_id, 'Rajesh Kumar', 'Cardiology', 'Cardiac Surgery', 'cardio@hospital.local', 1
FROM users u
WHERE u.username = 'doctor_cardiology'
  AND NOT EXISTS (SELECT 1 FROM doctors d WHERE d.user_id = u.user_id);

